/**
 * THE GAME'S INTERFACE (stage 3i): panels over the game (the pause menu, the settings, a dialogue
 * box), a HUD and the subtitles, in HTML generated by code, with the site's metal and ink (decision
 * 0008). What every panel shares: it is drawn over the whole game (a click outside it does not reach
 * the game), and it works with the keyboard alone: the arrows go from one control to the next (left and
 * right still move a slider), Tab stays inside, Enter or Space press, and whoever opened it says what
 * Escape does. The console stays above them (a tool to look inside, even with a menu open): a panel
 * that opens while someone types in it does not take the keys, and gets them when it closes.
 */

/** The styles, once per page. */
export function addInterfaceStyles() {
  if (document.getElementById('mg-ui-styles')) return;
  const style = document.createElement('style');
  style.id = 'mg-ui-styles';
  style.textContent = `
    .mg-veil {
      position: absolute; inset: 0; z-index: 15; display: grid; place-items: center;
      background: rgb(10 9 7 / 0.55);
    }
    .mg-panel {
      min-width: min(20rem, calc(100% - 2rem)); max-width: calc(100% - 2rem); box-sizing: border-box;
      max-height: calc(100% - 2rem); overflow-y: auto;
      padding: 1.1rem 1.3rem 1.2rem; border-radius: 0.5rem;
      background: rgb(18 16 13 / 0.95); border: 1px solid rgb(158 116 70 / 0.7);
      box-shadow: 0 18px 40px -16px rgb(0 0 0 / 0.95);
      color: #dcd2c3; font: 15px/1.5 system-ui, sans-serif;
    }
    .mg-panel h2 {
      margin: 0 0 0.8rem; color: #f0d59a; letter-spacing: 0.05em; text-align: center;
      font: 600 20px/1.3 'Cinzel Variable', Georgia, serif;
    }
    .mg-panel p { margin: 0 0 0.8rem; text-align: center; }
    .mg-panel .mg-small { font-size: 12px; color: #a99c88; margin: 0.7rem 0 0; }
    .mg-panel .mg-actions { display: flex; flex-direction: column; gap: 0.45rem; }
    .mg-panel .mg-actions.mg-row { flex-direction: row; justify-content: center; }
    .mg-panel button {
      padding: 0.45rem 1rem; border-radius: 0.35rem; cursor: pointer;
      border: 1px solid #24170a; color: #ead5b0;
      background: linear-gradient(160deg, #3c2916, #553c24 55%, #3f2b17);
      font: 600 15px/1.4 'Cinzel Variable', Georgia, serif; letter-spacing: 0.03em;
    }
    .mg-panel button:hover { filter: brightness(1.15); }
    .mg-panel :focus-visible { outline: 2px solid #93d9c9; outline-offset: 2px; }
    .mg-panel label { display: grid; grid-template-columns: 1fr auto; gap: 0.2rem 0.8rem; align-items: center; margin: 0 0 0.6rem; }
    .mg-panel label output { color: #93d9c9; font: 13px ui-monospace, Menlo, monospace; min-width: 2.5rem; text-align: right; }
    .mg-panel input[type='range'] { grid-column: 1 / -1; width: 100%; accent-color: #c4a06a; }
    .mg-panel input[type='checkbox'] { width: 1.1rem; height: 1.1rem; accent-color: #c4a06a; }
    .mg-hud {
      position: absolute; top: 12px; left: 12px; z-index: 10; pointer-events: none;
      display: flex; gap: 0.9rem; padding: 0.3rem 0.7rem; border-radius: 0.35rem;
      background: rgb(18 16 13 / 0.6); color: #f0d59a;
      font: 600 14px/1.4 'Cinzel Variable', Georgia, serif; letter-spacing: 0.03em;
    }
    .mg-hud span b { font: 600 14px ui-monospace, Menlo, monospace; color: #f3e9d8; margin-left: 0.3rem; }
    .mg-subtitles {
      position: absolute; left: 50%; transform: translateX(-50%); bottom: 64px; z-index: 10; pointer-events: none;
      display: flex; flex-direction: column; align-items: center; gap: 0.2rem; max-width: calc(100% - 2rem);
      font: 14px/1.35 system-ui, sans-serif; color: #f3e9d8;
    }
    .mg-subtitles div { padding: 0.15rem 0.55rem; border-radius: 0.25rem; background: rgb(10 9 7 / 0.72); transition: opacity 0.4s; }
    @media (prefers-reduced-motion: reduce) { .mg-subtitles div { transition: none; } }
    .mg-objective {
      position: absolute; top: 12px; left: 50%; transform: translateX(-50%); z-index: 10; pointer-events: none;
      padding: 0.3rem 0.8rem; border-radius: 0.35rem; background: rgb(18 16 13 / 0.6); color: #f0d59a;
      font: 600 14px/1.4 'Cinzel Variable', Georgia, serif; letter-spacing: 0.03em; max-width: calc(100% - 2rem);
    }
    .mg-scene {
      position: absolute; left: 50%; transform: translateX(-50%); top: 56px; z-index: 11; cursor: pointer;
      max-width: min(36rem, calc(100% - 2rem)); padding: 0.6rem 0.9rem; border-radius: 0.4rem;
      background: rgb(18 16 13 / 0.85); border: 1px solid #c4a06a; color: #f3e9d8; font: 15px/1.45 system-ui, sans-serif;
    }
    .mg-scene b { display: block; color: #f0d59a; font: 600 13px/1.4 'Cinzel Variable', Georgia, serif; letter-spacing: 0.04em; }
  `;
  document.head.append(style);
}

/** What can take the focus inside a box, in order. */
export function focusables(box: HTMLElement): HTMLElement[] {
  return [...box.querySelectorAll<HTMLElement>('button, input, select, textarea, [tabindex]:not([tabindex="-1"])')].filter(
    (el) => !el.hidden && !(el as HTMLButtonElement).disabled,
  );
}

/**
 * The keys every panel shares: up and down (and Tab) go from one control to the next, round; left and
 * right are a slider's. Returns whether it took the key.
 */
export function navigate(box: HTMLElement, e: KeyboardEvent): boolean {
  const all = focusables(box);
  if (all.length === 0) return false;
  const at = all.indexOf(document.activeElement as HTMLElement);
  const by = e.key === 'ArrowDown' || (e.key === 'Tab' && !e.shiftKey) ? 1 : e.key === 'ArrowUp' || e.key === 'Tab' ? -1 : 0;
  if (by === 0) return false;
  e.preventDefault();
  all[(at + by + all.length) % all.length]!.focus();
  return true;
}

/**
 * A panel over the game: a veil over all of it, and in the middle a box with its heading. `onKey` is
 * told every key pressed in it first (Escape, say); the arrows and Tab move the focus.
 */
export function panel(container: HTMLElement, o: { title: string; onKey?: (e: KeyboardEvent) => boolean }) {
  addInterfaceStyles();
  const veil = document.createElement('div');
  veil.className = 'mg-veil';
  // (It can take the focus: a click on it, outside a control, keeps the keys in the panel.)
  veil.tabIndex = -1;
  const box = document.createElement('div');
  box.className = 'mg-panel';
  box.setAttribute('role', 'dialog');
  box.setAttribute('aria-modal', 'true');
  const heading = document.createElement('h2');
  heading.textContent = o.title;
  box.setAttribute('aria-label', o.title);
  box.append(heading);
  veil.append(box);
  // Keys stay in the panel: the game, the console's bindings and the page do not see them.
  veil.addEventListener('keydown', (e) => {
    e.stopPropagation();
    if (o.onKey?.(e)) return void e.preventDefault();
    navigate(box, e);
  });
  // A click on the veil stays there too (the camera would take it as a drag).
  veil.addEventListener('pointerdown', (e) => e.stopPropagation());
  container.append(veil);
  return {
    box,
    heading,
    /** The focus on its first control (unless someone is typing in the console: it gets it when that closes). */
    focus() {
      if (document.activeElement?.closest('.mg-console')) return;
      focusables(box)[0]?.focus();
    },
    remove: () => veil.remove(),
  };
}

/** The keys to the last panel open over the game, if there is one (on its first control): whether there was. */
export function focusPanel(container: HTMLElement): boolean {
  const veils = container.querySelectorAll<HTMLElement>('.mg-veil');
  const last = veils[veils.length - 1];
  if (!last) return false;
  (focusables(last)[0] ?? last).focus();
  return true;
}

/** A button that says `text` and does `then`. */
export function button(text: string, then: () => void): HTMLButtonElement {
  const b = document.createElement('button');
  b.type = 'button';
  b.textContent = text;
  b.addEventListener('click', then);
  return b;
}
